#!/usr/bin/env node
/*
 * Patches the Android project generated by `expo prebuild` to require a release
 * signing configuration from Gradle project properties. No key, password, alias,
 * or certificate fingerprint is stored in this repository.
 *
 * Required Gradle properties:
 * - NARQA_RELEASE_STORE_FILE
 * - NARQA_RELEASE_STORE_PASSWORD
 * - NARQA_RELEASE_KEY_ALIAS
 * - NARQA_RELEASE_KEY_PASSWORD
 */
const fs = require("node:fs");
const path = require("node:path");

const androidDir = process.argv[2]
  ? path.resolve(process.argv[2])
  : path.resolve(__dirname, "..");
const gradlePath = path.join(androidDir, "app", "build.gradle");

if (!fs.existsSync(gradlePath)) {
  throw new Error(
    `Generated Android Gradle file not found: ${gradlePath}. Run Expo prebuild before configuring release signing.`,
  );
}

let gradle = fs.readFileSync(gradlePath, "utf8");
const signingMarker = "        // NARQA_RELEASE_SIGNING_CONFIG";
const releaseMarker = "            // NARQA_RELEASE_SIGNING_CONFIG";

if (gradle.includes(signingMarker) || gradle.includes(releaseMarker)) {
  throw new Error(
    "Release-signing markers already exist. Refusing to patch a generated Android project twice.",
  );
}

const requiredProperties = [
  "NARQA_RELEASE_STORE_FILE",
  "NARQA_RELEASE_STORE_PASSWORD",
  "NARQA_RELEASE_KEY_ALIAS",
  "NARQA_RELEASE_KEY_PASSWORD",
];

const propertyAssertions = requiredProperties
  .map(
    (property) =>
      `            if (!project.hasProperty('${property}')) throw new GradleException('Missing required Gradle property: ${property}')`,
  )
  .join("\n");

const releaseSigningConfig = `${signingMarker}
        release {
${propertyAssertions}
            storeFile file(project.property('NARQA_RELEASE_STORE_FILE'))
            storePassword project.property('NARQA_RELEASE_STORE_PASSWORD')
            keyAlias project.property('NARQA_RELEASE_KEY_ALIAS')
            keyPassword project.property('NARQA_RELEASE_KEY_PASSWORD')
        }
`;

const signingConfigsAnchor = "    }\n    buildTypes {";
if (!gradle.includes(signingConfigsAnchor)) {
  throw new Error(
    "Expected Expo Android buildTypes anchor was not found. Review the generated Gradle template before releasing.",
  );
}
gradle = gradle.replace(
  signingConfigsAnchor,
  `${releaseSigningConfig}    }\n    buildTypes {`,
);

const debugReleaseSigning = "            signingConfig signingConfigs.debug\n            def enableShrinkResources";
const releaseSigning = `${releaseMarker}\n            signingConfig signingConfigs.release\n            def enableShrinkResources`;
if (!gradle.includes(debugReleaseSigning)) {
  throw new Error(
    "Expected debug release-signing line was not found. Refusing to produce a release that might use an unknown signer.",
  );
}
gradle = gradle.replace(debugReleaseSigning, releaseSigning);

fs.writeFileSync(gradlePath, gradle, { encoding: "utf8", mode: 0o600 });
console.log(`Configured generated Android release signing at ${gradlePath}`);
